    fun setFloat(id: Int, prop: Int, v: Double)
    fun setString(id: Int, prop: Int, v: String)
    fun setColor(id: Int, prop: Int, v: Long)
    fun setEdges(id: Int, prop: Int, top: Float, right: Float, bottom: Float, left: Float)
    fun setEnum(id: Int, prop: Int, v: Int)
    /** [v] is valid only during the call. */
    fun setBytes(id: Int, prop: Int, v: ByteBuffer)
    fun setFrame(id: Int, x: Float, y: Float, width: Float, height: Float)
    fun listen(id: Int, event: Int)
