private fun ByteBuffer.take(n: Int): ByteBuffer {
    val s = slice().order(ByteOrder.LITTLE_ENDIAN)
    s.limit(n)
    position(position() + n)
    return s
}

private fun ByteBuffer.string(): String {
    val n = int
    val a = ByteArray(n)
    get(a)
    return String(a, Charsets.UTF_8)
}

/** Decodes a batch of ops (see ops/ops.go) into [h]. */
fun nuiDecode(data: ByteBuffer, h: NuiOpHandler) {
    val r = data.order(ByteOrder.LITTLE_ENDIAN)
    val n = r.int
    repeat(n) {
        val code = r.get().toInt() and 0xff
        val id = r.int
        when (code) {
            1 -> h.create(id, r.short.toInt() and 0xffff)
            2 -> h.destroy(id)
            3 -> { val child = r.int; h.insert(id, child, r.int) }
            4 -> h.remove(id, r.int)
            5 -> {
                val prop = r.short.toInt() and 0xffff
                when (val t = r.get().toInt()) {
                    1 -> h.setBool(id, prop, r.get().toInt() != 0)
                    2 -> h.setInt(id, prop, r.long)
                    3 -> h.setFloat(id, prop, r.double)
                    4 -> h.setString(id, prop, r.string())
                    5 -> h.setColor(id, prop, r.long)
                    6 -> h.setEdges(id, prop, r.float, r.float, r.float, r.float)
                    7 -> h.setEnum(id, prop, r.int)
                    8 -> h.setBytes(id, prop, r.take(r.int))
                    else -> error("nui: bad value type $t")
                }
            }
            6 -> h.setFrame(id, r.float, r.float, r.float, r.float)
            7 -> h.listen(id, r.short.toInt() and 0xffff)
            8 -> h.unlisten(id, r.short.toInt() and 0xffff)
            9 -> { val cmd = r.short.toInt() and 0xffff; h.command(id, cmd, r.take(r.int)) }
            10 -> h.setRoot(id)
            else -> error("nui: bad op code $code")
        }
    }
}

