    val width: Float = 0f, val height: Float = 0f,
    val safeTop: Float = 0f, val safeRight: Float = 0f, val safeBottom: Float = 0f, val safeLeft: Float = 0f,
    val keyboard: Float = 0f,
    val scale: Float = 1f,
    val fontScale: Float = 1f,
    val dark: Boolean = false,
    val reduceMotion: Boolean = false,
    val locale: String = "",
    val timeZone: String = java.util.TimeZone.getDefault().id,
)

/** Writes the little-endian wire format. */
class NuiWriter {
    private var buf = ByteBuffer.allocate(64).order(ByteOrder.LITTLE_ENDIAN)
    private fun room(n: Int) {
        if (buf.remaining() < n) {
            val b = ByteBuffer.allocate(maxOf(buf.capacity() * 2, buf.position() + n)).order(ByteOrder.LITTLE_ENDIAN)
            buf.flip()
            b.put(buf)
            buf = b
        }
    }
    fun u8(v: Int) { room(1); buf.put(v.toByte()) }
    fun u16(v: Int) { room(2); buf.putShort(v.toShort()) }
    fun u32(v: Int) { room(4); buf.putInt(v) }
    fun u64(v: Long) { room(8); buf.putLong(v) }
    fun f32(v: Float) { room(4); buf.putFloat(v) }
    fun f64(v: Double) { room(8); buf.putDouble(v) }
    fun string(v: String) { val a = v.toByteArray(Charsets.UTF_8); u32(a.size); room(a.size); buf.put(a) }
    fun header(id: Int, kind: Int) { u32(id); u16(kind) }
    fun environment(e: NuiEnvironment) {
        for (f in floatArrayOf(e.width, e.height, e.safeTop, e.safeRight, e.safeBottom, e.safeLeft, e.keyboard, e.scale, e.fontScale)) f32(f)
        u8((if (e.dark) 1 else 0) or (if (e.reduceMotion) 2 else 0))
        string(e.locale)
        string(e.timeZone)
    }
    fun gesture(g: NuiGesture) {
        u8(g.state)
        for (f in floatArrayOf(g.x, g.y, g.translationX, g.translationY, g.velocityX, g.velocityY, g.scale)) f32(f)
    }
    fun raw(v: ByteArray) { room(v.size); buf.put(v) }
    fun bytes(): ByteArray = buf.array().copyOf(buf.position())
}

